mapper.select:
SELECT *
FROM orders
WHERE merchant_id = #{merchantId}


    AND status = #{status}



    AND (
    order_no LIKE CONCAT('%', #{keyword}, '%')
    OR remark LIKE CONCAT('%', #{keyword}, '%')
    OR JSON_UNQUOTE(JSON_EXTRACT(address_snapshot, '$.name')) LIKE CONCAT('%', #{keyword}, '%')
    OR JSON_UNQUOTE(JSON_EXTRACT(address_snapshot, '$.phone')) LIKE CONCAT('%', #{keyword}, '%')
    )



    AND create_time  >=  #{startTime}



    AND create_time  <=  #{endTime}


ORDER BY create_time DESC
